/* Module-owned native state; generated by tools/ram_map.py accessors.
 * The address view serializes fields explicitly, independent of C padding
 * and host byte order. Unmoved variables still use state_host's image. */
#ifndef CT_PORT_VARS_HOST_H
#define CT_PORT_VARS_HOST_H

#include <stdbool.h>
#include <stdint.h>

typedef struct {
    struct {
        uint16_t id;
        uint8_t x;
        uint8_t y;
        uint8_t flags;
    } location;
    struct {
        uint16_t id;
        uint8_t x;
        uint8_t y;
        uint8_t flags;
    } location_previous;
    struct {
        uint16_t id;
        uint8_t x;
        uint8_t y;
        uint8_t flags;
    } location_next;
    struct {
        uint16_t id;
        uint8_t x;
        uint8_t y;
        uint8_t flags;
    } location_stored;
} VarsHostLocations;

typedef struct {
    VarsHostLocations locations;
} VarsHost;

void vars_host_init(VarsHost *h);
bool vars_host_read8(const VarsHost *h, uint32_t addr, uint8_t *value);
bool vars_host_write8(VarsHost *h, uint32_t addr, uint8_t value);

#endif
